struct QuitGlobalData { unsigned char pad[0xa9e]; char disabled; };
struct QuitGate { char check(); };
struct QuitGameLogic { unsigned char pad[0x10c]; int mode; };
class QuitWindow { public: virtual void hide(int); virtual void s1(); virtual void s2(); virtual void s3(); virtual void show(int); virtual void commit(); };
class QuitShell { public: QuitWindow *top(); };
extern QuitGlobalData *TheWritableGlobalData;
extern QuitGate *g_quitGate;
extern QuitGameLogic *TheBfmeGameLogic;
extern QuitShell *TheShell;
void bfmeApplyQuitScreen(int kind, int mode, int enabled);

class BfmeAptScreenQuitMenu {
public:
	void _bfme_saveMenu(const char *argument);
};

void BfmeAptScreenQuitMenu::_bfme_saveMenu(const char *)
{
	char enabled = TheWritableGlobalData->disabled == 0;
	if (g_quitGate->check()) enabled = !enabled;
	if (enabled) {
		int gameMode = TheBfmeGameLogic->mode;
		int menuMode;
		if (gameMode == 1 || gameMode == 5) menuMode = 4;
		else menuMode = (gameMode == 2) + 1;
		bfmeApplyQuitScreen(3, menuMode, 1);
	} else {
		QuitWindow *window = TheShell->top();
		window->hide(0);
		window->show(0);
		window->commit();
	}
}
